package com.zhou.craft.repo;import com.zhou.craft.model.CraftOrder;import org.springframework.data.jpa.repository.JpaRepository;import java.util.*;
public interface CraftOrderRepository extends JpaRepository<CraftOrder,Long>{List<CraftOrder> findAllByOrderByCreatedAtDesc();List<CraftOrder> findByCustomerIdOrderByCreatedAtDesc(Long customerId);List<CraftOrder> findByCreatorIdOrderByCreatedAtDesc(Long creatorId);List<CraftOrder> findByCustomerNameOrderByCreatedAtDesc(String customerName);}